482:         const snapshot = structuredClone({ ...target, id: id('canvas-revision'), parentId: this.headId });
483:         this.record.snapshots[snapshot.id] = snapshot;
484:         this.changes.push({ snapshots: { [snapshot.id]: snapshot }, diagramRevisions: {} });
485:         this.record.past.push(this.headId); this.record.headId = snapshot.id; this.record.future = [];
